// Final test: verify the complete game works by testing key functionality
const player = { x: 0, y: -5, z: 0, vx: 0, vy: 0, vz: 0, health: 100, speed: 3 };
console.log('Player object:', JSON.stringify(player));

// Test wave generation logic
function generateWave(wave) {
    const enemies = [];
    const count = Math.min(3 + wave * 2, 15);
    for (let i = 0; i < count; i++) {
        const types = ['basic', 'fast', 'tank'];
        const type = types[i % types.length];
        enemies.push({
            x: (Math.random() - 0.5) * 30,
            y: 10 + Math.random() * 20,
            z: 40,
            vx: 0, vy: 0, vz: 0,
            type: type,
            health: type === 'tank' ? 50 : (type === 'fast' ? 20 : 15),
            radius: type === 'tank' ? 1.5 : 1,
            scoreValue: type === 'basic' ? 10 : (type === 'fast' ? 15 : 20)
        });
    }
    return enemies;
}

const wave = generateWave(3);
console.log('Wave 3 has', wave.length, 'enemies');

